+)
+
+// EOL describes the end of standard and, where offered, extended OS support.
+type EOL struct {
+	StandardSupportUntil time.Time
+	ExtendedSupportUntil time.Time
+	Ended                bool
+}
+
+// IsStandardSupportEnded reports whether standard support has ended at now.
+func (e EOL) IsStandardSupportEnded(now time.Time) bool {
+	return e.Ended || (!e.StandardSupportUntil.IsZero() && now.After(e.StandardSupportUntil))
+}
+
+// IsExtendedSuppportEnded reports whether an applicable extended phase has ended.
+func (e EOL) IsExtendedSuppportEnded(now time.Time) bool {
+	return !e.ExtendedSupportUntil.IsZero() && now.After(e.ExtendedSupportUntil)
+}
+
+func eolDate(value string) time.Time {
+	date, err := time.Parse("2006-01-02", value)
+	if err != nil {
+		panic(err)
+	}
+	return date
+}
+
+func support(standard, extended string) EOL {
+	e := EOL{StandardSupportUntil: eolDate(standard)}
+	if extended != "" {
+		e.ExtendedSupportUntil = eolDate(extended)
+	}
+	return e
+}
+
+var eolByFamily = map[string]map[string]EOL{
